WITH returns_detail AS ( SELECT cr.cr_order_number AS order_number, cr.cr_returned_date_sk AS returned_date_sk, cr.cr_return_amount, cr.cr_return_tax, cr.cr_return_ship_cost, cr.cr_fee, cr.cr_net_loss, cc.cc_name, sm.sm_ship_mode_id, w.w_warehouse_name, (cr.cr_return_amount - cr.cr_return_tax - cr.cr_return_ship_cost - cr.cr_fee) AS adjusted_return_amount FROM catalog_returns cr JOIN call_center cc ON cr.cr_call_center_sk = cc.cc_call_center_sk JOIN ship_mode sm ON cr.cr_ship_mode_sk = sm.sm_ship_mode_sk JOIN warehouse w ON cr.cr_warehouse_sk = w.w_warehouse_sk ), running_totals AS ( SELECT rd.*, SUM(adjusted_return_amount) OVER (PARTITION BY cc_name ORDER BY returned_date_sk ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_adj_return, PERCENT_RANK() OVER (ORDER BY adjusted_return_amount DESC) AS pct_rank_adj_return, LAG(adjusted_return_amount) OVER (PARTITION BY cc_name ORDER BY returned_date_sk) AS prev_adj_return FROM returns_detail rd ) SELECT order_number, returned_date_sk, cc_name, sm_ship_mode_id, w_warehouse_name, adjusted_return_amount, prev_adj_return, cumulative_adj_return, pct_rank_adj_return, CASE WHEN pct_rank_adj_return < 0.2 THEN 'Top 20%' WHEN pct_rank_adj_return < 0.5 THEN 'Middle 30%' ELSE 'Bottom 50%' END AS performance_bucket FROM running_totals WHERE pct_rank_adj_return <= 0.9 ORDER BY cumulative_adj_return DESC LIMIT 20
